reference_solution:
def maximum_interval_overlap(intervals):
    events = []
    for start, end in intervals: events.extend([(start, 1), (end, -1)])
    active = best = 0
    for _, delta in sorted(events, key=lambda event: (event[0], event[1])):
        active += delta; best = max(best, active)
    return best

